// SUPPLIED: reference treasure-hunt rules (pure, no DOM, clock or randomness).
// They agree with the shared fixtures F01-F11 (tests/fixtures/treasure) and the
// course game contract. You do not edit this file in W2.10.

export type Direction = "north" | "east" | "south" | "west";
export type Status = "playing" | "won" | "lost";
export type Reason = "WALL" | "EDGE" | "INVALID_ACTION" | "GAME_COMPLETE";

export interface Point {
  readonly x: number;
  readonly y: number;
}

export interface Treasure extends Point {
  readonly id: string;
  readonly value: number;
}

/** Local rule definition. The wire field `initialMoves` becomes `initialMoveBudget` here. */
export interface Board {
  readonly id: string;
  readonly width: number;
  readonly height: number;
  readonly start: Point;
  readonly walls: readonly Point[];
  readonly treasures: readonly Treasure[];
  readonly exit: Point;
  readonly initialMoveBudget: number;
}

export interface GameState {
  position: Point;
  movesRemaining: number;
  score: number;
  collected: string[];
  status: Status;
}

export interface MoveAction {
  type: "move";
  direction: Direction;
}

export interface MoveResult {
  accepted: boolean;
  reason: Reason | null;
  state: GameState;
}

export const DIRECTIONS: Readonly<Record<Direction, Point>> = {
  north: { x: 0, y: -1 },
  east: { x: 1, y: 0 },
  south: { x: 0, y: 1 },
  west: { x: -1, y: 0 },
};

export function isDirection(value: unknown): value is Direction {
  return typeof value === "string" && Object.hasOwn(DIRECTIONS, value);
}

export function initialState(board: Board): GameState {
  return {
    position: { x: board.start.x, y: board.start.y },
    movesRemaining: board.initialMoveBudget,
    score: 0,
    collected: [],
    status: "playing",
  };
}

/** A complete, independent copy: callers can never change a state they were given. */
export function copyState(state: GameState): GameState {
  return {
    position: { x: state.position.x, y: state.position.y },
    movesRemaining: state.movesRemaining,
    score: state.score,
    collected: [...state.collected],
    status: state.status,
  };
}

function reject(state: GameState, reason: Reason): MoveResult {
  return { accepted: false, reason, state: copyState(state) };
}

/** Evaluate one action. Never mutates `board`, `state` or `action`. */
export function evaluate(board: Board, state: GameState, action: unknown): MoveResult {
  if (state.status !== "playing") return reject(state, "GAME_COMPLETE");
  const candidate = action as Partial<MoveAction> | null | undefined;
  if (!candidate || candidate.type !== "move" || !isDirection(candidate.direction)) {
    return reject(state, "INVALID_ACTION");
  }
  const step = DIRECTIONS[candidate.direction];
  const x = state.position.x + step.x;
  const y = state.position.y + step.y;
  if (x < 0 || y < 0 || x >= board.width || y >= board.height) return reject(state, "EDGE");
  if (board.walls.some((w) => w.x === x && w.y === y)) return reject(state, "WALL");

  // 1. Move and charge one move.
  const next = copyState(state);
  next.position = { x, y };
  next.movesRemaining -= 1;
  // 2. An uncollected treasure scores once and records its identity.
  for (const t of board.treasures) {
    if (t.x === x && t.y === y && !next.collected.includes(t.id)) {
      next.collected.push(t.id);
      next.score += t.value;
    }
  }
  // 3. The exit wins only when every treasure identity has been collected.
  //    This is checked before the zero-budget loss, so a final-move win counts.
  const allCollected = board.treasures.every((t) => next.collected.includes(t.id));
  if (x === board.exit.x && y === board.exit.y && allCollected) next.status = "won";
  // 4. Otherwise an empty budget loses.
  else if (next.movesRemaining === 0) next.status = "lost";
  return { accepted: true, reason: null, state: next };
}
